/**
 * Знайти місто в підкапотній базі 40 міст за текстом або назвою
 */
export const findCityInDatabase = (rawText) => {
  if (!rawText || typeof rawText !== "string") return null;
  const clean = rawText.trim().toLowerCase().replace(/^(погода\s+(в|у)?\s*)/i, "").trim();
  if (!clean) return null;

  for (const city of UKRAINE_CITIES_40) {
    if (city.name.toLowerCase() === clean) return city;
    if (city.aliases.some((alias) => alias.toLowerCase() === clean)) return city;
  }

  // Спробуємо частковий збіг (наприклад, якщо користувач ввів "конотоп погода" або "погода конотоп зараз")
  for (const city of UKRAINE_CITIES_40) {
    if (city.aliases.some((alias) => clean.includes(alias.toLowerCase()))) {
      return city;
    }
  }

  return null;
};
